from pydantic import BaseModel, Field, field_validator
from typing import Optional
from enum import Enum
import uuid

class TxnState(str, Enum):
    INITIATED  = "INITIATED"
    PROCESSING = "PROCESSING"
    SUCCESS    = "SUCCESS"
    FAILED     = "FAILED"

class PaymentRequest(BaseModel):
    idempotency_key: str        = Field(..., min_length=8, max_length=64)
    payer_vpa: str              = Field(..., pattern=r"^[\w.\-]+@[\w]+$")
    payee_vpa: str              = Field(..., pattern=r"^[\w.\-]+@[\w]+$")
    amount_paise: int           = Field(..., gt=0, description="Amount in paise. ₹1 = 100")
    remarks: Optional[str]      = Field(None, max_length=128)

    @field_validator("amount_paise")
    @classmethod
    def max_limit(cls, v):
        if v > 100_000_00:  # ₹1,00,000 UPI limit
            raise ValueError("Exceeds UPI limit of ₹1,00,000")
        return v

class PaymentResponse(BaseModel):
    txn_id: str
    status: TxnState
    bank_rrn: Optional[str]   = None
    message: str
    source: str               = "NEW"  # NEW | CACHED

class TxnRecord(BaseModel):
    txn_id: str               = Field(default_factory=lambda: str(uuid.uuid4()))
    idempotency_key: str
    payer_vpa: str
    payee_vpa: str
    amount_paise: int
    remarks: Optional[str]    = None
    state: TxnState           = TxnState.INITIATED
    bank_code: Optional[str]  = None
    bank_rrn: Optional[str]   = None
    error: Optional[str]      = None
    created_at: str           = ""
    updated_at: str           = ""
